SELECT CAST(COUNT(CASE WHEN p.dischtime IS NOT NULL AND p.dischtime - p.admittime >= 7 THEN 1 END) AS FLOAT) / NULLIF(COUNT(CASE WHEN p.dod IS NOT NULL THEN 1 END), 0) AS alive_to_dead_ratio, PERCENT_RANK() OVER (ORDER BY (p.dischtime - p.admittime)) AS percentile_rank FROM patients p JOIN admissions a ON p.subject_id = a.subject_id WHERE p.gender = 'F' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) BETWEEN 59 AND 69 AND a.admission_type = 'E' ORDER BY alive_to_dead_ratio NULLS LAST, percentile_rank NULLS LAST;